package com.example.rootmanager

import android.os.Build
import java.io.BufferedReader
import java.io.DataOutputStream
import java.io.File
import java.io.InputStreamReader

object RootHelper {

    /**
         * Mengecek keberadaan file biner 'su' di jalur umum sistem
              * tanpa memicu pop-up permintaan izin root.
                   */
                       fun isSuBinaryPresent(): Boolean {
                               val paths = arrayOf(
                                           "/system/app/Superuser.apk",
                                                       "/sbin/su",
                                                                   "/system/bin/su",
                                                                               "/system/xbin/su",
                                                                                           "/data/local/xbin/su",
                                                                                                       "/data/local/bin/su",
                                                                                                                   "/system/sd/xbin/su",
                                                                                                                               "/system/bin/failsafe/su",
                                                                                                                                           "/data/local/su",
                                                                                                                                                       "/su/bin/su"
                                                                                                                                                               )
                                                                                                                                                                       for (path in paths) {
                                                                                                                                                                                   if (File(path).exists()) return true
                                                                                                                                                                                           }
                                                                                                                                                                                                   return false
                                                                                                                                                                                                       }

                                                                                                                                                                                                           /**
                                                                                                                                                                                                                * Meminta akses root secara aktif melalui eksekusi shell 'su'.
                                                                                                                                                                                                                     * Ini akan memicu dialog persetujuan dari Magisk / KernelSU / SuperSU.
                                                                                                                                                                                                                          */
                                                                                                                                                                                                                              fun requestRootAccess(): Pair<Boolean, String> {
                                                                                                                                                                                                                                      var process: Process? = null
                                                                                                                                                                                                                                              return try {
                                                                                                                                                                                                                                                          process = Runtime.getRuntime().exec("su")
                                                                                                                                                                                                                                                                      val os = DataOutputStream(process.outputStream)
                                                                                                                                                                                                                                                                                  val reader = BufferedReader(InputStreamReader(process.inputStream))

                                                                                                                                                                                                                                                                                              // Menjalankan perintah sederhana 'id' untuk memverifikasi hak akses uid=0
                                                                                                                                                                                                                                                                                                          os.writeBytes("id\n")
                                                                                                                                                                                                                                                                                                                      os.writeBytes("exit\n")
                                                                                                                                                                                                                                                                                                                                  os.flush()

                                                                                                                                                                                                                                                                                                                                              val output = reader.readLine() ?: ""
                                                                                                                                                                                                                                                                                                                                                          val exitCode = process.waitFor()

                                                                                                                                                                                                                                                                                                                                                                      if (exitCode == 0 && output.contains("uid=0")) {
                                                                                                                                                                                                                                                                                                                                                                                      Pair(true, "Akses Root Diberikan ($output)")
                                                                                                                                                                                                                                                                                                                                                                                                  } else {
                                                                                                                                                                                                                                                                                                                                                                                                                  Pair(false, "Akses Root Ditolak oleh pengguna atau pengelola root.")
                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (e: Exception) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                  Pair(false, "Gagal mengeksekusi su: ${e.message}")
                                                                                                                                                                                                                                                                                                                                                                                                                                                          } finally {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      process?.destroy()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      /**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           * Menjalankan perintah shell dengan hak akses root setelah mendapat persetujuan.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    fun executeRootCommand(command: String): String {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var process: Process? = null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val output = StringBuilder()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        process = Runtime.getRuntime().exec("su")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val os = DataOutputStream(process.outputStream)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                val reader = BufferedReader(InputStreamReader(process.inputStream))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            val errorReader = BufferedReader(InputStreamReader(process.errorStream))

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        os.writeBytes("$command\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    os.writeBytes("exit\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                os.flush()

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var line: String?
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        while (reader.readLine().also { line = it } != null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        output.append(line).append("\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                while (errorReader.readLine().also { line = it } != null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                output.append("[ERR] ").append(line).append("\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        process.waitFor()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    output.toString().trim().ifEmpty { "Perintah selesai tanpa output." }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (e: Exception) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Error eksekusi: ${e.message}"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } finally {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            process?.destroy()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 * Mengambil informasi dasar perangkat keras dan perangkat lunak.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          fun getDeviceInfo(): String {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return """
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Model Perangkat : ${Build.MANUFACTURER.uppercase()} ${Build.MODEL}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Versi Android   : ${Build.VERSION.RELEASE} (SDK ${Build.VERSION.SDK_INT})
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Arsitektur CPU  : ${Build.SUPPORTED_ABIS.joinToString(", ")}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Build Tags      : ${Build.TAGS}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          """.trimIndent()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              